(() => {

  const raw = String($json.Timestamp || "");
  if (!raw) return "NO";

  // Match: 12/28/2025 3:20:49
  const m = raw.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})\s+(\d{1,2}):(\d{2}):(\d{2})$/);

  if (!m) return "NO";

  const hour = Number(m[4]);

  // Night window: 10PM → 6AM
  return (hour >= 22 || hour < 6) ? "YES" : "NO";

})()
}}

