(() => {

  const val = $json["Color Pages"];

  // Handle empty/null/0
  if (
    val === null ||
    val === undefined ||
    val.toString().trim() === "" ||
    val.toString().trim() === "0"
  ) {
    return 0;
  }

  return val
    .toString()
    .split(",")
    .map(v => v.trim())
    .filter(v => v !== "")
    .length;

})()
}}

