const batch_metadata = $("assign_order_id").first().json;

const updated_counters = batch_metadata.updated_counters || {};
const batch_id = batch_metadata.batch_id;

const updated_at = new Date().toISOString();

return Object.entries(updated_counters).map(
  ([college_code, last_order_number]) => ({
    json: {
      college_code,
      last_order_number,
      updated_at,
      batch_id,
    },
  })
);

parameters.pythonCode:
rows = _input.all()

college_counters = {}

for item in rows:

    data = item.json or {}

    college_code = data.get("college_code")
    last_number = data.get("last_order_number")

    # strict validation
    if not college_code or last_number is None:
        continue

    code = str(college_code).strip()

    # store latest value per college
    college_counters[code] = int(last_number)

return [{
    "json": college_counters
}]

